private val PoracodeThemePresetsById = PoracodeThemePresets.associateBy { it.id }

/** Resolve a persisted theme id to its preset, falling back to default. */
fun poracodeThemePreset(id: String?): PoracodeThemePreset =
    PoracodeThemePresetsById[normalizeThemeId(id)] ?: PoracodeThemePresetsById.getValue(DEFAULT_PORACODE_THEME_ID)

const val DEFAULT_PORACODE_THEME_ID = "default"

/** Map legacy persisted ids onto the PWA/iOS theme ids; unknown -> default. */
fun normalizeThemeId(id: String?): String {
    val mapped = when (id) {
        "lightcode-legacy" -> "poracode-legacy"
        null -> DEFAULT_PORACODE_THEME_ID
        else -> id
    }
    return if (PoracodeThemePresetsById.containsKey(mapped)) mapped else DEFAULT_PORACODE_THEME_ID
}
